interface RoadDriveable {
    void steerOnRoad(int degrees);
}

interface WaterNavigable {
    void engagePropeller(int rpm);
}

class Vehicle {
    protected String vin;
    public Vehicle(String vin) { this.vin = vin; }
}

// Extends 1 class, implements 2 interfaces
class AmphibiousCar extends Vehicle implements RoadDriveable, WaterNavigable {
    public AmphibiousCar(String vin) {
        super(vin);
    }

    public void steerOnRoad(int degrees) {
        System.out.println(vin + " steering on asphalt by " + degrees + " degrees");
    }

    public void engagePropeller(int rpm) {
        System.out.println(vin + " water propeller spinning at " + rpm + " RPM");
    }
}

public class InterfaceInheritanceDemo {
    public static void main(String[] args) {
        AmphibiousCar car = new AmphibiousCar("AMPH-772");
        car.steerOnRoad(15);
        car.engagePropeller(2400);
    }
}

