interface LoggerAlpha {
    default void logMessage(String msg) {
        System.out.println("[ALPHA] " + msg);
    }
}

interface LoggerBeta {
    default void logMessage(String msg) {
        System.out.println("[BETA] " + msg);
    }
}

// Explicit resolution prevents Diamond collision
class DualLogger implements LoggerAlpha, LoggerBeta {
    public void logMessage(String msg) {
        // Explicitly choose LoggerAlpha or implement custom logic
        LoggerAlpha.super.logMessage(msg);
        System.out.println("Dispatched via DualLogger");
    }
}

public class DefaultCollisionDemo {
    public static void main(String[] args) {
        DualLogger dl = new DualLogger();
        dl.logMessage("System health OK");
    }
}

