interface Transferable {
    void transferFunds(String target, double amount);
}

interface Auditable {
    void generateAuditRecord();
}

class BankAccount implements Transferable, Auditable {
    private String accountId;
    private double balance;

    public BankAccount(String id, double balance) {
        this.accountId = id;
        this.balance = balance;
    }

    public void transferFunds(String target, double amount) {
        if (balance >= amount) {
            balance -= amount;
            System.out.println("Transferred $" + amount + " from " + accountId + " to " + target + ". Remaining balance: $" + balance);
        }
    }

    public void generateAuditRecord() {
        System.out.println("AUDIT LOG: Account " + accountId + " verified with active balance $" + balance);
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount acc = new BankAccount("ACC-101", 2000.0);
        acc.transferFunds("ACC-202", 400.0);
        acc.generateAuditRecord();
    }
}

interface CloudStore {
    default void backup() {
        System.out.println("Backing up to AWS S3");
    }
}

interface LocalStore {
    default void backup() {
        System.out.println("Backing up to Local NAS");
    }
}

class HybridStorage implements CloudStore, LocalStore {
    public void backup() {
        CloudStore.super.backup();
        LocalStore.super.backup();
        System.out.println("[SUCCESS] Redundant backup cycle completed");
    }
}

public class Main {
    public static void main(String[] args) {
        HybridStorage storage = new HybridStorage();
        storage.backup();
    }
}

