class Vehicle {
    protected String vin;
    public Vehicle(String vin) { this.vin = vin; }
}

interface SelfDriving {
    void calculateRoute(String dest);
}

interface PassengerCarrier {
    void boardPassenger(int count);
}

interface FareCalculator {
    double computeFare(double distance, double rate);
}

class AutonomousTaxi extends Vehicle implements SelfDriving, PassengerCarrier, FareCalculator {
    public AutonomousTaxi(String vin) {
        super(vin);
    }
    public void calculateRoute(String dest) {
        System.out.println("Vehicle " + vin + " navigating to " + dest);
    }
    public void boardPassenger(int count) {
        System.out.println("Boarded " + count + " passengers");
    }
    public double computeFare(double distance, double rate) {
        return distance * rate;
    }
}

public class Main {
    public static void main(String[] args) {
        AutonomousTaxi taxi = new AutonomousTaxi("TAXI-99");
        taxi.calculateRoute("Airport");
        taxi.boardPassenger(2);
        double fare = taxi.computeFare(14.5, 2.50);
        System.out.println("Trip Fare for 14.5 miles: $" + fare);
    }
}
